using namespace std;

class Solution {
public:
    string nextPalindromicPermutation(string s) {
        int n = s.size();
        string half = s.substr(0, n / 2);
        int i = (int)half.size() - 2;
        while (i >= 0 && half[i] >= half[i + 1]) {
            i--;
        }
        if (i < 0) return "";
        int j = (int)half.size() - 1;
        while (half[j] <= half[i]) {
            j--;
        }
        swap(half[i], half[j]);
        reverse(half.begin() + i + 1, half.end());
        string mid = (n % 2 == 1) ? string(1, s[n / 2]) : "";
        string rev_half = half;
        reverse(rev_half.begin(), rev_half.end());
        return half + mid + rev_half;
    }
};

import java.util.*;

class Solution {
    public String nextPalindromicPermutation(String s) {
        int n = s.length();
        char[] half = s.substring(0, n / 2).toCharArray();
        int i = half.length - 2;
        while (i >= 0 && half[i] >= half[i + 1]) {
            i--;
        }
        if (i < 0) return "";
        int j = half.length - 1;
        while (half[j] <= half[i]) {
            j--;
        }
        char t = half[i]; half[i] = half[j]; half[j] = t;
        int l = i + 1, r = half.length - 1;
        while (l < r) {
            char tmp = half[l]; half[l] = half[r]; half[r] = tmp;
            l++; r--;
        }
        String first = new String(half);
        String mid = (n % 2 == 1) ? String.valueOf(s.charAt(n / 2)) : "";
        String rev = new StringBuilder(first).reverse().toString();
        return first + mid + rev;
    }
}

var nextPalindromicPermutation = function(s) {
    const n = s.length;
    const half = s.slice(0, Math.floor(n / 2)).split('');
    let i = half.length - 2;
    while (i >= 0 && half[i] >= half[i + 1]) {
        i--;
    }
    if (i < 0) return "";
    let j = half.length - 1;
    while (half[j] <= half[i]) {
        j--;
    }
    [half[i], half[j]] = [half[j], half[i]];
    let l = i + 1, r = half.length - 1;
    while (l < r) {
        [half[l], half[r]] = [half[r], half[l]];
        l++; r--;
    }
    const first = half.join('');
    const mid = (n % 2 === 1) ? s[Math.floor(n / 2)] : "";
    const rev = half.reverse().join('');
    return first + mid + rev;
};
